  }

  public async save(snapshot: ReplaySnapshot): Promise<void> {
    const dir = path.join(this.baseDir, snapshot.sessionId);
    await fsx.ensureDir(dir);
    const file = path.join(dir, `${snapshot.stepId}.json`);
    await fsx.writeJson(
      file,
      {
        ...snapshot,
        createdAt: snapshot.createdAt ?? new Date().toISOString()
      },
      { spaces: 2 }
    );
  }

  public async list(sessionId: string): Promise<ReplaySnapshot[]> {
    const dir = path.join(this.baseDir, sessionId);
    if (!(await fsx.pathExists(dir))) {
      return [];
    }
    const files = await fsx.readdir(dir);
    const snapshots: ReplaySnapshot[] = [];
    for (const file of files.sort()) {
      const full = path.join(dir, file);
      const data = await fsx.readJson(full);
      snapshots.push(data as ReplaySnapshot);
    }
    return snapshots;
  }
}
