import { EventEmitter } from "node:events";
import type { RuntimeApprovalPayload } from "@compliance/runtime-gate";

export type LiveApprovalDecision = {
  requestId: string;
  approved: boolean;
  decidedBy: string;
  decidedAt: string;
  latencyMs: number;
  rationale?: string;
};

export interface LiveApprovalChannelEvents {
  request: [RuntimeApprovalPayload];
  decision: [LiveApprovalDecision];
}

type EventKey = keyof LiveApprovalChannelEvents;

class LiveApprovalChannel extends EventEmitter {
  publish(payload: RuntimeApprovalPayload): void {
    this.emit("request", payload);
  }

  notifyDecision(decision: LiveApprovalDecision): void {
    this.emit("decision", decision);
  }

  waitForDecision(requestId: string): Promise<LiveApprovalDecision> {
    return new Promise((resolve) => {
      const handler = (decision: LiveApprovalDecision) => {
        if (decision.requestId === requestId) {
          this.off("decision", handler);
          resolve(decision);
        }
      };
      this.on("decision", handler);
    });
  }

  on<Event extends EventKey>(event: Event, listener: (...args: LiveApprovalChannelEvents[Event]) => void): this {
    return super.on(event, listener);
  }
}

export const liveApprovalChannel = new LiveApprovalChannel();
