import { liveApprovalChannel } from "@gate-ui/services/live-approval-channel";
import { LiveApprovalRepository } from "@state-store/live-approval-repository";

export class ApprovalTimeoutWatchdog {
  private readonly repository: LiveApprovalRepository;
  private timers = new Map<string, NodeJS.Timeout>();

  constructor(repository = new LiveApprovalRepository()) {
    this.repository = repository;
  }

  public watch(input: {
    requestId: string;
    sessionId: string;
    planId: string;
    trigger: string;
    timeoutMs: number;
  }): void {
    if (this.timers.has(input.requestId)) {
      clearTimeout(this.timers.get(input.requestId)!);
    }

    const timer = setTimeout(async () => {
      const decidedAt = new Date().toISOString();
      const decision = {
        requestId: input.requestId,
        sessionId: input.sessionId,
        planId: input.planId,
        trigger: input.trigger,
        approved: false,
        decidedBy: "timeout",
        decidedAt,
        latencyMs: input.timeoutMs,
        rationale: "Approval timeout"
      };
      await this.repository.record(decision);
      liveApprovalChannel.notifyDecision(decision);
      this.timers.delete(input.requestId);
    }, input.timeoutMs);

    this.timers.set(input.requestId, timer);
  }

  public clear(requestId: string): void {
    const timer = this.timers.get(requestId);
    if (timer) {
      clearTimeout(timer);
      this.timers.delete(requestId);
    }
  }
}

export const approvalTimeoutWatchdog = new ApprovalTimeoutWatchdog();
