{"command":["bash","-lc","cat <<'EOF' > src/live/sla-summary.ts
export interface SlaMetric {
  name: string;
  valueMs: number;
  thresholdMs: number;
  description?: string;
  severity?: "info" | "warning" | "critical";
}

export interface SlaSummary {
  sessionId: string;
  metrics: SlaMetric[];
  breaches: SlaMetric[];
}

export interface SlaInput {
  sessionId: string;
  gateLatencySamples?: number[];
  pauseResumeSamples?: number[];
  timeoutMs?: number;
}

const DEFAULT_THRESHOLDS = {
  gateLatencyMs: 200,
  pauseResumeMs: 200
};

export function summarizeSla(input: SlaInput): SlaSummary {
  const metrics: SlaMetric[] = [];

  if (input.gateLatencySamples?.length) {
    const avg = average(input.gateLatencySamples);
    metrics.push({
      name: "gateLatencyMs",
      valueMs: avg,
      thresholdMs: DEFAULT_THRESHOLDS.gateLatencyMs,
      description: `Average of ${input.gateLatencySamples.length} samples`
    });
  }

  if (input.pauseResumeSamples?.length) {
    const avg = average(input.pauseResumeSamples);
    metrics.push({
      name: "pauseResumeMs",
      valueMs: avg,
      thresholdMs: DEFAULT_THRESHOLDS.pauseResumeMs,
      description: `Average of ${input.pauseResumeSamples.length} samples`
    });
  }

  const breaches = metrics.filter((metric) => metric.valueMs > metric.thresholdMs);

  return {
    sessionId: input.sessionId,
    metrics,
    breaches
  };
}

function average(values: number[]): number {
  const sum = values.reduce((acc, value) => acc + value, 0);
  return Math.round(sum / values.length);
}
EOF
"]}

{"command":["bash","-lc","cat <<'EOF' > src/live/report-generator.ts
import path from "node:path";
import fsx from "fs-extra";
import { StateStore } from "@state-store/index";
import { ReplayPlanRepository } from "@state-store/replay-plan-repository";
import { summarizeSla } from "./sla-summary";

export interface GenerateReportOptions {
  baseDir?: string;
  reportsDir?: string;
  store?: StateStore;
  writeToFile?: boolean;
}

export interface LiveSessionReport {
  session: ReturnType<StateStore["getLiveSession"]>;
  approvals: ReturnType<StateStore["listLiveApprovals"]>;
  telemetryBundles: Array<{ file: string; generatedAt: string }>;
  sla: ReturnType<typeof summarizeSla>;
  replayPlan: Awaited<ReturnType<ReplayPlanRepository["list"]>>;
}

export async function generateLiveSessionReport(
  sessionId: string,
  options: GenerateReportOptions = {}
): Promise<LiveSessionReport> {
  const baseDir = path.resolve(options.baseDir ?? "var/live-sessions");
  const reportsDir = path.resolve(options.reportsDir ?? "reports/live-sessions");
  const store = options.store ?? StateStore.getInstance();
  const repository = new ReplayPlanRepository(path.join(baseDir, "replay"));

  const session = store.getLiveSession(sessionId);
  if (!session) {
    throw new Error(`Live session ${sessionId} not found`);
  }

  const approvals = store.listLiveApprovals(sessionId);
  const telemetryDir = path.join(baseDir, "telemetry", sessionId);
  const telemetryBundles: Array<{ file: string; generatedAt: string }> = [];

  if (await fsx.pathExists(telemetryDir)) {
    const files = await fsx.readdir(telemetryDir);
    for (const file of files) {
      const full = path.join(telemetryDir, file);
      const stats = await fsx.stat(full);
      telemetryBundles.push({
        file: full,
        generatedAt: stats.mtime.toISOString()
      });
    }
  }

  const gateLatencies = approvals.map((approval) => approval.latencyMs).filter(Boolean) as number[];
  const pauseResumeSamples = session.metadata?.pauseResumeMs as number[] | undefined;

  const sla = summarizeSla({
    sessionId,
    gateLatencySamples: gateLatencies,
    pauseResumeSamples
  });

  const replayPlan = await repository.list(sessionId);

  const report: LiveSessionReport = {
    session,
    approvals,
    telemetryBundles,
    sla,
    replayPlan
  };

  if (options.writeToFile) {
    await fsx.ensureDir(reportsDir);
    const file = path.join(reportsDir, `${sessionId}.json`);
    await fsx.writeJson(file, report, { spaces: 2 });
  }

  return report;
}
EOF
"]}

