#!/usr/bin/env tsx
import path from "node:path";
import fsx from "fs-extra";
import { Command } from "commander";

const program = new Command();

program
  .option("--base-dir <path>", "Base directory for live artifacts", "var/live-sessions")
  .option("--max-age <hours>", "Retention window in hours", "2160"); // 90 days

program.parse(process.argv);

const options = program.opts<{ baseDir: string; maxAge: string }>();
const thresholdMs = Number(options.maxAge) * 60 * 60 * 1000;

async function removeIfOld(filePath: string) {
  const stats = await fsx.stat(filePath);
  const ageMs = Date.now() - stats.mtime.getTime();
  if (ageMs > thresholdMs) {
    await fsx.remove(filePath);
    return true;
  }
  return false;
}

async function purgeDirectory(directory: string) {
  if (!(await fsx.pathExists(directory))) return 0;
  const items = await fsx.readdir(directory);
  let removed = 0;
  for (const item of items) {
    const full = path.join(directory, item);
    const stats = await fsx.stat(full);
    if (stats.isDirectory()) {
      removed += await purgeDirectory(full);
      const contents = await fsx.readdir(full).catch(() => []);
      if (contents.length === 0) {
        await fsx.remove(full);
      }
      continue;
    }
    if (await removeIfOld(full)) {
      removed += 1;
    }
  }
  return removed;
}

async function main() {
  const baseDir = path.resolve(options.baseDir);
  const removed = await purgeDirectory(baseDir);
  console.log(`Removed ${removed} expired artifacts from ${baseDir}`);
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});
EOF
